//! Original Tables policy over two local-file source passes; DATA only.
use crate::{captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},reactive_raw_policy_pages::RawPolicyPages,reactive_reads_native::Failure,lint::{Site,AllowUse}};
use std::{io,sync::Arc,collections::BTreeSet};
pub struct TablesData{sites:Vec<Site>,source_text:Vec<String>,allow_used:Vec<AllowUse>}
impl TablesData{pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}}
fn oom(s:impl Into<String>)->Failure{Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,s.into()))}
fn charge(b:&Budget,n:Option<usize>)->Result<(),Failure>{let n=n.ok_or_else(||{b.deny();oom("Tables data admission overflow")})?;b.charge(n).map_err(oom)}
fn poll(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(oom)?;poll()?;b.require().map_err(oom)}
fn own(b:&Budget,s:&str)->Result<String,Failure>{charge(b,s.len().checked_add(64))?;Ok(s.to_owned())}
fn row<T>(b:&Budget,v:&mut Vec<T>)->Result<(),Failure>{if v.len()<v.capacity(){return Ok(())}let n=v.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||oom("Tables vector overflow"))?;charge(b,n.checked_mul(4).and_then(|n|n.checked_mul(std::mem::size_of::<T>())).and_then(|n|n.checked_add(64)))?;v.try_reserve_exact(n-v.len()).map_err(|_|oom("Tables vector allocation refused"))?;if v.capacity()>n.saturating_mul(4){b.deny();return Err(oom("Tables exposed vector capacity exceeds reservation"))}Ok(())}
struct FileRows{relative:String,sites:Vec<Site>,text:Vec<String>,allowed:Vec<AllowUse>}
fn file_rows(views:RawPolicyViews<'_>,roots:&BTreeSet<String>,b:&Budget,p:&dyn Fn()->io::Result<()>)->Result<FileRows,Failure>{let f=views.source_file()?;let found=crate::sys_tables_policy::judge(f,roots);let mut out=FileRows{relative:own(b,&f.rel)?,sites:Vec::new(),text:Vec::new(),allowed:Vec::new()};for(rule,line)in found{let rule=crate::sys_tables_policy::RULES.get(rule as usize).ok_or("Tables original rule ordinal unavailable")?.name;let line=line as usize;poll(b,p)?;let allow_name=format!("sys_{rule}");if let Some(kept)=crate::allow::kept(f,line,&allow_name){let value=AllowUse{rel:own(b,&f.rel)?,line:kept.line as u32,name:own(b,&allow_name)?,code:kept.code.unwrap_or_default()};charge(b,value.code.capacity().checked_add(64))?;if !out.allowed.contains(&value){row(b,&mut out.allowed)?;out.allowed.push(value)}continue}let site=Site{rule:own(b,rule)?,rel:own(b,&f.rel)?,line:line as u32,msg:String::new(),key:String::new(),ident:String::new()};let source=f.raw();let source=if line>0&&line<=source.num_lines(){source.line(line)}else{""};charge(b,source.len().checked_add(64))?;let text=crate::util::normalize_ws(source);row(b,&mut out.sites)?;row(b,&mut out.text)?;out.sites.push(site);out.text.push(text);}Ok(out)}
/// Both passes must report actual EOF. That boolean is still only DATA; the
/// host's two actual selected-domain completion tokens remain mandatory.
pub fn collect<P:RawPolicyPages+?Sized>(pages:&P,config:&Config,b:&Arc<Budget>,p:&dyn Fn()->io::Result<()>)->Result<TablesData,Failure>{
 let pending=collect_using(pages,config,b,p);if matches!(&pending,Err(Failure::Operational(_))){return pending}poll(b,p)?;pending
}
fn collect_using<P:RawPolicyPages+?Sized>(pages:&P,config:&Config,b:&Arc<Budget>,p:&dyn Fn()->io::Result<()>)->Result<TablesData,Failure>{
 poll(b,p)?;let scope=config.borrowed_policy_scope("sys/tables","sys");let selected=|relative:&str|crate::dm::sys::policy_selection().matches_path(relative)&&!scope.is_some_and(|s|s.exempt(relative));let mut roots=BTreeSet::<String>::new();
 let complete=pages.for_each(&mut|relative,views|{poll(b,p)?;if !selected(relative){return Ok(true)}let file=views.source_file()?;if file.rel!=relative{return Err("Tables original file label differs".into())}for name in crate::sys_tables_policy::global_lists_of(file){poll(b,p)?;if !roots.contains(&name){charge(b,name.capacity().checked_add(1024+std::mem::size_of::<String>()))?;roots.insert(name);}}Ok(true)})?;if !complete{return Err("Tables global-list-name source pass stopped before EOF".into())}poll(b,p)?;
 let mut files=Vec::<FileRows>::new();let complete=pages.for_each(&mut|relative,views|{poll(b,p)?;if !selected(relative){return Ok(true)}if views.source_file()?.rel!=relative{return Err("Tables original file label differs".into())}let value=file_rows(views,&roots,b,p)?;row(b,&mut files)?;files.push(value);Ok(true)})?;if !complete{return Err("Tables judgement source pass stopped before EOF".into())}poll(b,p)?;
 charge(b,files.len().checked_mul(2*std::mem::size_of::<FileRows>()).and_then(|n|n.checked_add(128)))?;files.sort_by(|a,b|a.relative.cmp(&b.relative));let mut result=TablesData{sites:Vec::new(),source_text:Vec::new(),allow_used:Vec::new()};for file in files{for value in file.allowed{if !result.allow_used.contains(&value){row(b,&mut result.allow_used)?;result.allow_used.push(value)}}for(site,text)in file.sites.into_iter().zip(file.text){row(b,&mut result.sites)?;row(b,&mut result.source_text)?;result.sites.push(site);result.source_text.push(text)}}poll(b,p)?;Ok(result)
}

#[cfg(all(test,feature="legacy-sem"))]#[path="sys_tables_frozen_original.rs"]mod original;
#[cfg(all(test,feature="legacy-sem"))]mod tests{
 use super::*;use crate::{captured_raw_file::{File,Config},captured_raw_policy::Configuration,lint::{Registry,Cx,Sink},tree::{Tree,SourceFile}};use std::cell::Cell;
 struct Pages{files:Vec<(String,String)>,calls:Cell<usize>,stop:Option<usize>,fail:Option<usize>}
 impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let pass=self.calls.get();self.calls.set(pass+1);if self.fail==Some(pass){return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}let root=std::env::current_dir().unwrap();for(rel,text)in &self.files{let file=File::capture(&root,&root.join(rel),text.clone().into())?;if !file.with_policy_views(visit)?{return Ok(false)}}Ok(self.stop!=Some(pass))}}
 fn pages()->Pages{Pages{files:vec![("maps/names.dm".into(),"GLOBAL_LIST_INIT(shared, list(1,2))
".into()),("code/reader.dm".into(),"/obj/probe/values()
	return GLOB.shared
/obj/probe/constant()
	return list(1,2)
/obj/probe/local()
	var/static/list/items = list(1)
	return items
// ALLOW(instance_list): not worth it
".into())],calls:Cell::new(0),stop:None,fail:None}}

 #[test]fn tables_whole_original_findings_exceed_finite_fixture_cardinality(){let mut p=pages();let seed=p.files[1].1.lines().filter(|line|!line.contains("ALLOW(")).collect::<Vec<_>>().join("\n")+"\n";p.files.retain(|(rel,_)|rel.starts_with("maps/"));for index in 0..101{p.files.push((format!("code/large{index:04}.dm"),seed.repeat(101)));}let tree=Tree::from_files(p.files.iter().map(|(rel,text)|SourceFile::from_text(rel,text)).collect());let mut registry=Registry::default();super::original::register(&mut registry);let lint=registry.find("sys/tables").unwrap();let scopes=crate::scopes::Scopes::default();let scope=scopes.for_lint("sys/tables","sys");let mut expected=Sink::new();lint.scan_tree(&Cx{tree:&tree,meta:lint.meta(),scope:&scope},&mut expected);assert!(expected.sites.len()>10_000);let config=Config::capture(Configuration::ProvenMissing).unwrap();let actual=collect(&p,&config,&Budget::new(256*1024*1024).unwrap(),&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.sites);assert_eq!(actual.allow_used(),expected.allow_used);}
 #[test]fn full_tables_two_pass_fold_matches_whole_original_global_lists_and_findings_order(){let p=pages();let tree=Tree::from_files(p.files.iter().map(|(rel,text)|SourceFile::from_text(rel,text)).collect());let mut registry=Registry::default();super::original::register(&mut registry);let lint=registry.find("sys/tables").unwrap();for bytes in [None,Some(br#"[lint."sys/tables"]
exempt_files=['maps/names.dm']
"#.as_slice())]{let config=Config::capture(bytes.map_or(Configuration::ProvenMissing,Configuration::Captured)).unwrap();let scopes=bytes.map(|bytes|crate::scopes::Scopes::parse(std::str::from_utf8(bytes).unwrap()).unwrap()).unwrap_or_default();let scope=scopes.for_lint("sys/tables","sys");let mut expected=Sink::new();lint.scan_tree(&Cx{tree:&tree,meta:lint.meta(),scope:&scope},&mut expected);let data=collect(&p,&config,&Budget::new(8*1024*1024).unwrap(),&||Ok(())).unwrap();assert_eq!(data.sites(),expected.sites);assert_eq!(data.allow_used(),expected.allow_used);assert!(data.sites().iter().any(|s|s.rule=="const_list_alloc"));assert!(data.sites().iter().any(|s|s.rule=="static_getter"));for(site,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,tree.site_text(&site.rel,site.line as usize));}}}
 #[test]fn tables_names_without_completed_judgement_never_return_partial_output(){let config=Config::capture(Configuration::ProvenMissing).unwrap();for stopped in [0,1]{let mut p=pages();p.stop=Some(stopped);assert!(collect(&p,&config,&Budget::new(8*1024*1024).unwrap(),&||Ok(())).is_err())}let mut p=pages();p.fail=Some(1);let actual=collect(&p,&config,&Budget::new(8*1024*1024).unwrap(),&||Ok(())).err().unwrap();assert!(matches!(actual,Failure::Operational(ref e)if e.raw_os_error()==Some(1450)));let p=pages();let tiny=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let actual=collect(&p,&config,&tiny,&||Ok(())).err().unwrap();assert!(matches!(actual,Failure::Operational(ref e)if e.kind()==io::ErrorKind::OutOfMemory));assert!(collect(&p,&config,&Budget::new(8*1024*1024).unwrap(),&||Ok(())).is_ok());}
}

#[cfg(all(test,feature="legacy-sem"))]mod final_control_tests{
 use super::*;use std::cell::Cell;struct Stopped<'a>(&'a Cell<bool>);impl RawPolicyPages for Stopped<'_>{fn for_each(&self,_:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{self.0.set(true);Ok(false)}}
 #[test]fn tables_stopped_provider_late_control_preserves_actual_interruption(){let stopped=Cell::new(false);let config=Config::capture(crate::captured_raw_policy::Configuration::ProvenMissing).unwrap();let budget=Budget::new(8192).unwrap();let error=collect(&Stopped(&stopped),&config,&budget,&||if stopped.get(){Err(io::Error::new(io::ErrorKind::Interrupted,"actual final control"))}else{Ok(())}).err().unwrap();assert!(matches!(error,Failure::Operational(ref error)if error.kind()==io::ErrorKind::Interrupted));}
}
